async function compile(ws, rec, ctl) {
  const out = path.join(ws, "build/classes");
  rmrf(path.join(ws, "build")); fs.mkdirSync(out, { recursive: true });
  const cp = fs.readFileSync(path.join(CP_DIR, `${rec.mcVersion}.txt`), "utf8").trim();
  const sources = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")).map((f) => f.abs);
  const r = await run("javac", ["-J-Xmx768m", "--release", "21", "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", out, ...sources],
    { cwd: ws, env: childEnv(false), timeout: 180000, track: ctl });
  ctl.child = null;
  const output = (r.err + r.out).split(ws + "/").join("");
  if (r.code !== 0) return { ok: false, errors: output.slice(0, 12000) };
  // Resources (plugin.yml, config.yml, ...)
  copyDir(path.join(ws, "src/main/resources"), out);
  const jar = path.join(ws, "build/plugin.jar");
  // Reproducible jar: sorted entries + a fixed entry timestamp (JDK 19+ `--date`), so the same source gives the same bytes.
  // If this JDK rejects --date, fall back to the old unsorted form rather than failing the build.
  const rel = (f) => f.rel.slice("build/classes/".length);
  const entries = jarEntries(listFiles(ws, "build/classes").map(rel));
  let j = await run("jar", jarArgs(jar, out, entries), { cwd: ws, env: childEnv(false), timeout: 60000 });
  if (j.code !== 0 && /--date|illegal option|unrecognized option|usage/i.test(j.err + j.out)) {
    j = await run("jar", ["--create", "--file", jar, "-C", out, "."], { cwd: ws, env: childEnv(false), timeout: 60000 });
  }
  if (j.code !== 0) return { ok: false, errors: j.err.slice(0, 4000) };
  const warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 10);
  return { ok: true, jar, classes: out, warnings };
}

